//! The `wasm32` test registry for `temper-design-bundle`.
//!
//! Generated by `scripts/gen_wasm_test_registry.py`; run it after adding a
//! test to any listed module, and `--check` gates drift in CI.
//!
//! `cargo test`'s libtest harness cannot target `wasm32-unknown-unknown`,
//! so the Worker tier calls each test function individually instead of
//! running a test binary.  This module is the flat, indexable list of them.
//!
//! Only modules that survive `--no-default-features` appear here.  Tests
//! inside `#[cfg(feature = "python")]` modules are structurally absent
//! from a `wasm32` build and cannot be registered here at all.
//!
//! Two exclusion classes apply here, both structural:
//!
//! * `#[cfg(feature = "python")]` modules.  This crate is mostly a
//!   pyo3 boundary -- the great majority of its modules are declared
//!   under that gate in `lib.rs` -- so most of its `#[test]` functions
//!   do not exist in a `--no-default-features` build.  They are not
//!   skipped on `wasm32`: they are not compiled, exactly as they are
//!   not compiled by the crate's own default-feature `cargo test`.
//! * `proptest` modules use a dev-dependency, which is not linked into
//!   the ordinary (non-test) build this registry compiles into.
//!
//! `scripts/gen_wasm_test_registry.py --crate temper-design-bundle
//! --census` prints the full module census with per-module counts.
//!
//! ## Families
//!
//! Each module entry in `ALL` is gated on a `wasm-registry-<family>`
//! feature, as in `temper-drc-rs`.  This crate declares a single
//! family (`design-bundle`): what survives `--no-default-features`
//! is a flat set of parsers and validators with no taxonomy to shard
//! along.

/// A single test: its fully qualified name and a nullary callable.
///
/// Failure is signalled by panicking, exactly as under libtest.  On
/// `wasm32-unknown-unknown` a panic aborts (the target has no unwinding on
/// stable), which surfaces to the host as a WebAssembly trap -- so the
/// runner catches the trap rather than a `Result`.
pub type WasmTest = (&'static str, fn());

/// All 60 eligible tests, in a stable order.  Each entry is
/// gated on the per-family `wasm-registry-<family>` feature; enable
/// all families (`wasm-test-registry`) or individual ones.
pub const ALL: &[&[WasmTest]] = &[
    #[cfg(feature = "wasm-registry-design-bundle")] crate::constraint_merge::tests::WASM_TESTS,
    #[cfg(feature = "wasm-registry-design-bundle")] crate::identity::board_identity_tests::WASM_TESTS,
    #[cfg(feature = "wasm-registry-design-bundle")] crate::kicad_pcb::tests::WASM_TESTS,
    #[cfg(feature = "wasm-registry-design-bundle")] crate::net_class_validation::tests::WASM_TESTS,
    #[cfg(feature = "wasm-registry-design-bundle")] crate::netlist::tests::WASM_TESTS,
    #[cfg(feature = "wasm-registry-design-bundle")] crate::pad_occurrence::tests::WASM_TESTS,
    #[cfg(feature = "wasm-registry-design-bundle")] crate::parse_engine::tests::WASM_TESTS,
    #[cfg(feature = "wasm-registry-design-bundle")] crate::pcl::tests::WASM_TESTS,
    #[cfg(feature = "wasm-registry-design-bundle")] crate::pcl::real_pcl_tests::WASM_TESTS,
    #[cfg(feature = "wasm-registry-design-bundle")] crate::safety_value::tests::WASM_TESTS,
];

/// Total number of registered tests *in the currently-selected families*.
pub fn count() -> usize {
    ALL.iter().map(|m| m.len()).sum()
}

/// The test at `index` in the flattened registry.
pub fn get(index: usize) -> Option<&'static WasmTest> {
    let mut remaining = index;
    for module in ALL {
        if remaining < module.len() {
            return Some(&module[remaining]);
        }
        remaining -= module.len();
    }
    None
}
